(async()=>{
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let store;try{const response=await fetch('/api/catalog',{cache:'no-store'});if(!response.ok)throw Error();store=await response.json()}catch{const grid=document.querySelector('#product-grid');if(grid)grid.innerHTML='<p class="empty" role="alert">O catálogo está temporariamente indisponível. Atualize a página para tentar novamente.</p>';return}
const st=store.settings;document.documentElement.style.setProperty('--brand-blue',st.color);document.title=!!document.querySelector('.products-page')?'Produtos | '+st.name:st.name;
document.querySelectorAll('.brand-logo').forEach(img=>{img.src=st.logo;img.alt=st.name});document.querySelector('link[rel="icon"]').href=st.favicon;
const headline=document.querySelector('.hero h1');if(headline)headline.innerHTML=escapeHTML(st.headline)+'<br><em>'+escapeHTML(st.highlight)+'</em>';
const heroDescription=document.querySelector('.hero-copy>p');if(heroDescription)heroDescription.textContent=st.description;
const heroImage=document.querySelector('.hero-visual img');if(heroImage)heroImage.src=st.heroImage;
if(window.renderHeroBanners)window.renderHeroBanners(store);
document.querySelectorAll('.demo-notice').forEach(el=>el.classList.toggle('hidden',!st.demo));
document.querySelectorAll('a[href^="https://wa.me/"]').forEach(a=>{const url=new URL(a.href);url.pathname='/'+st.phone;a.href=url.href});
const phoneDisplay=st.phone.length===13&&st.phone.startsWith('55')?'('+st.phone.slice(2,4)+') '+st.phone.slice(4,9)+'-'+st.phone.slice(9):'+'+st.phone;
const topPhone=document.querySelector('.topbar a');if(topPhone)topPhone.textContent='Atendimento: '+phoneDisplay;
const phoneLink=document.querySelector('a[href^="tel:"]');if(phoneLink){phoneLink.href='tel:+'+st.phone;phoneLink.textContent=phoneDisplay}
const details=document.querySelector('.contact-details');if(details){for(const value of [st.address,st.hours])if(value){const p=document.createElement('p');p.textContent=value;details.append(p)}}
const reviewPhotos={'Rodrigo Rodrigues':'https://lh3.googleusercontent.com/a-/ALV-UjWHch4CPun_GK4MIG4eybQacjcMHy61oCTgaDJ0I6L7yMEEWdwBuA=s64-c-rp-mo-br100','Anthony Vinicius':'https://lh3.googleusercontent.com/a-/ALV-UjWvDTzwYCfVf0uBshh6xl7KNcvu7oPVFR1onQ_nSHxevFTnhrDi=s64-c-rp-mo-br100','Diego Mota':'https://lh3.googleusercontent.com/a/ACg8ocIGoFuLv6I6kd8nfoY5svfchUBZqCGGe4mtw7ru3BX5UsLOiIfk=s64-c-rp-mo-br100','Mayara Alves':'https://lh3.googleusercontent.com/a-/ALV-UjVRP89IgG6ozwRjz8mKU86o04kwnJmBBIei1UOKG9QZjZ99jxFCVg=s64-c-rp-mo-br100','Emanuely Victória':'https://lh3.googleusercontent.com/a-/ALV-UjXG0BQdKdiDLCMLqZs_JaRerI57IDVxzdXzrlDvVctta0Q2-Xpf7A=s64-c-rp-mo-br100','Larice Ramos':'https://lh3.googleusercontent.com/a/ACg8ocKKKLckCBhV6kNHfkimXT_0RO7f3D3tCB0FmGrBbGMvUnvESg=s64-c-rp-mo-br100'};
document.querySelectorAll('.review-card').forEach(card=>{const name=card.querySelector('strong')?.textContent.trim();const src=reviewPhotos[name];if(!src)return;const photo=document.createElement('img');photo.className='review-avatar';photo.src=src;photo.alt='Foto de '+name;card.prepend(photo)});
const reviewStyle=document.createElement('style');reviewStyle.textContent='.review-card{position:relative}.review-avatar{width:44px;height:44px;border-radius:50%;object-fit:cover;background:#e6e9fa;margin-bottom:12px;display:block}.review-card strong{display:block;margin-top:18px;font-size:.875rem}.product-detail-link{display:inline-block;color:#2a31aa;font-size:.82rem;font-weight:700;margin:4px 0 15px;text-decoration:underline;text-underline-offset:3px}';document.head.append(reviewStyle);
const filters=document.querySelector('.filters');if(filters)filters.innerHTML=['Todos',...store.categories].map(c=>'<button type="button" data-filter="'+escapeHTML(c)+'" aria-pressed="'+(c==='Todos')+'" class="'+(c==='Todos'?'active':'')+'">'+escapeHTML(c)+'</button>').join('');
const categoryStrip=document.querySelector('.category-strip');if(categoryStrip)categoryStrip.innerHTML=store.categories.map(c=>'<a href="produtos.html"><span>'+escapeHTML(c)+'</span></a>').join('');
const footerName=document.querySelector('footer .container>span');if(footerName)footerName.innerHTML='© <span id="year">'+new Date().getFullYear()+'</span> '+escapeHTML(st.name);
const ICONS = {
cart:'<circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>',
laptop:'<path d="M4 17V5a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v12M2 17h20l-2 4H4z"/>',
monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>',
printer:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6zM18 12h.01"/>',
cpu:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M9 9h6v6H9zM9 1v3m6-3v3M9 20v3m6-3v3M1 9h3m-3 6h3m16-6h3m-3 6h3"/>',
message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/>',
wrench:'<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94z"/>',
search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',
info:'<circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4h.01"/>',
close:'<path d="m18 6-12 12M6 6l12 12"/>',
drive:'<rect x="2" y="3" width="20" height="18" rx="2"/><path d="M2 15h20m-5 3h.01M7 7h10"/>',
mouse:'<rect x="5" y="2" width="14" height="20" rx="7"/><path d="M12 6v4"/>',
refresh:'<path d="M3 11a9 9 0 0 1 15.4-6.4L21 7M21 3v4h-4M21 13A9 9 0 0 1 5.6 19.4L3 17M3 21v-4h4"/>',
shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11zM9 12l2 2 4-4"/>'
};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.cpu}</svg>`}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon))}
const PRODUCTS=store.products;
const SERVICES=store.services;
const PHONE=store.settings.phone;
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);
const wa=text=>`https://wa.me/${PHONE}?text=${encodeURIComponent(text)}`;
let filter='Todos';let cart=new Map();let toastTimer;
try { const saved=JSON.parse(sessionStorage.getItem('sos-cart')||'[]'); if(Array.isArray(saved)) for(const item of saved) if(Array.isArray(item)&&PRODUCTS.some(p=>p.id===item[0]&&p.mode==='cart')&&Number.isInteger(item[1])&&item[1]>0&&item[1]<=10) cart.set(item[0],item[1]); } catch {}
const normalizeSearch=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
function showToast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}

function productGallery(p){const photos=Array.isArray(p.images)?p.images:(p.image?[p.image]:[]);if(!photos.length)return icon(p.icon);if(photos.length===1)return '<img class="product-photo" src="'+escapeHTML(photos[0])+'" alt="'+escapeHTML(p.name)+'" loading="lazy">';return '<div class="product-carousel" data-carousel data-index="0" role="group" aria-roledescription="carrossel" aria-label="Fotos de '+escapeHTML(p.name)+'">'+photos.map((src,i)=>'<img class="product-photo carousel-slide" src="'+escapeHTML(src)+'" alt="'+escapeHTML(p.name)+' — foto '+(i+1)+' de '+photos.length+'" '+(i?'hidden ':'')+'loading="lazy">').join('')+'<div class="carousel-controls carousel-dots" aria-label="Selecionar foto">'+photos.map((_,i)=>'<button type="button" data-slide-index="'+i+'" aria-label="Mostrar foto '+(i+1)+' de '+photos.length+'" aria-pressed="'+(i===0)+'"></button>').join('')+'</div></div>'}

function renderProducts(){const query=normalizeSearch(document.querySelector('#search').value.trim());const visible=PRODUCTS.filter(p=>(filter==='Todos'||p.category===filter)&&normalizeSearch(`${escapeHTML(p.name)} ${escapeHTML(p.category)} ${escapeHTML(p.description)}`).includes(query));document.querySelector('#product-grid').innerHTML=visible.map(p=>`<article class="product-card"><div class="product-top"><div class="product-icon">${productGallery(p)}<a class="product-photo-link" href="produto.html?id=${encodeURIComponent(p.id)}" aria-label="Ver produto: ${escapeHTML(p.name)}"></a></div><span class="badge ${p.mode==='whatsapp'?'consult':''}">${p.mode==='cart'?'Compra pelo site*':'Via WhatsApp'}</span></div><div class="product-body"><div class="product-category">${escapeHTML(p.category)}</div><h3><a class="product-name-link" href="produto.html?id=${encodeURIComponent(p.id)}">${escapeHTML(p.name)}</a></h3><a class="product-detail-link" href="produto.html?id=${encodeURIComponent(p.id)}">Ver detalhes do produto</a><p>${escapeHTML(p.description)}</p><div class="price">${p.price!==null?money(p.price):'Sob consulta'}</div><span class="price-note">${p.price!==null?(store.settings.demo?'Valor ilustrativo • item de exemplo':'Consulte condições e disponibilidade'):'Consulte modelos e disponibilidade'}</span>${p.mode==='cart'?`<button type="button" class="button outline" data-add="${p.id}">${icon('cart')} Adicionar ao carrinho</button>`:`<a class="button outline" href="${wa(`Olá! Vi a categoria ${escapeHTML(p.name)} no site da SOS. Gostaria de consultar modelos, preços e disponibilidade.`)}" target="_blank" rel="noopener noreferrer">${icon('message')} Consultar opções</a>`}</div></article>`).join('');document.querySelector('#empty-products').classList.toggle('hidden',visible.length>0);const resultCount=document.querySelector('#results-count');if(resultCount)resultCount.textContent=visible.length===1?'1 produto encontrado':`${visible.length} produtos encontrados`}
function setFilter(value){if(!['Todos',...store.categories].includes(value))throw new Error('Categoria inválida');filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===value);b.setAttribute('aria-pressed',String(b.dataset.filter===value))});renderProducts()}
function getCart(){const items=[...cart].map(([id,quantity])=>{const p=PRODUCTS.find(p=>p.id===id);return{id,name:p.name,quantity,price:p.price,lineTotal:p.price*quantity}});return{items,total:items.reduce((s,p)=>s+p.lineTotal,0),count:items.reduce((s,p)=>s+p.quantity,0),demonstration:store.settings.demo}}
function addToCart(id){const p=PRODUCTS.find(p=>p.id===id);if(!p||p.mode!=='cart')throw new Error('Produto indisponível para o carrinho');if((cart.get(id)||0)>=10){showToast('Limite de 10 unidades por item.');return getCart()}cart.set(id,(cart.get(id)||0)+1);renderCart();showToast(`${escapeHTML(p.name)} adicionado ao carrinho.`);return getCart()}
function renderCart(){try{sessionStorage.setItem('sos-cart',JSON.stringify([...cart]))}catch{}const state=getCart();document.querySelector('#cart-count').textContent=state.count;document.querySelector('#open-cart').setAttribute('aria-label',`Abrir carrinho, ${state.count} itens`);document.querySelector('#cart-items').innerHTML=state.items.length?state.items.map(p=>`<div class="cart-item"><div><h3>${escapeHTML(p.name)}</h3><p>${money(p.price)} por unidade</p><div class="quantity"><button class="icon-button" data-quantity="${p.id}" data-change="-1" aria-label="Diminuir quantidade de ${escapeHTML(p.name)}">−</button><output aria-label="Quantidade de ${escapeHTML(p.name)}">${p.quantity}</output><button class="icon-button" data-quantity="${p.id}" data-change="1" aria-label="Aumentar quantidade de ${escapeHTML(p.name)}" ${p.quantity>=10?'disabled':''}>+</button><button class="remove" data-remove="${p.id}">Remover</button></div></div><strong>${money(p.lineTotal)}</strong></div>`).join(''):`<div class="empty-cart">${icon('cart')}<h3>Seu carrinho está vazio</h3><p>Explore os produtos e adicione os itens que deseja.</p><button class="button primary full" data-close="cart-dialog">Explorar produtos</button></div>`;document.querySelector('#cart-summary').innerHTML=state.items.length?`<div class="cart-total"><span>${store.settings.demo?'Subtotal ilustrativo':'Subtotal'}</span><strong>${money(state.total)}</strong></div><p class="small-note">* Compra pelo site em preparação. ${store.settings.demo?'Itens e valores de demonstração. ':''}Frete, estoque e pagamento precisam ser confirmados.</p><button class="button primary full" id="review-order">Revisar seleção</button>`:''}
function openDialog(id){const d=document.getElementById(id);if(!d.open)d.showModal()}
function reviewOrder(){if(!getCart().items.length)return;sessionStorage.setItem('sos-cart',JSON.stringify([...cart]));sessionStorage.removeItem('sos-order-request');location.href='membros.html?checkout=1'}

document.addEventListener('click',event=>{const b=event.target.closest('[data-add],[data-filter],[data-category],[data-close],[data-quantity],[data-remove],#open-cart,#review-order,#back-cart');if(!b)return;if(b.dataset.add)addToCart(b.dataset.add);if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.category){document.querySelector('#search').value='';setFilter(b.dataset.category)}if(b.dataset.close)document.getElementById(b.dataset.close).close();if(b.dataset.remove){cart.delete(b.dataset.remove);renderCart()}if(b.dataset.quantity){const id=b.dataset.quantity;const next=(cart.get(id)||0)+Number(b.dataset.change);if(next<=0)cart.delete(id);else cart.set(id,Math.min(10,next));renderCart()}if(b.id==='open-cart')openDialog('cart-dialog');if(b.id==='review-order')reviewOrder();if(b.id==='back-cart'){document.querySelector('#checkout-dialog').close();openDialog('cart-dialog')}});
document.querySelector('#search').addEventListener('input',renderProducts);
if(document.querySelector('#service-grid')) document.querySelector('#service-grid').innerHTML=SERVICES.map(s=>`<article class="service-card"><div class="service-icon">${icon(s.icon)}</div><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.description)}</p><a href="${wa(`Olá! Gostaria de um orçamento para ${s.name.toLocaleLowerCase('pt-BR')}. Meu equipamento é: `)}" target="_blank" rel="noopener noreferrer">Solicitar orçamento</a></article>`).join('');
document.querySelector('#year').textContent=new Date().getFullYear();hydrateIcons();renderProducts();renderCart();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const schemas={type:'object',properties:{},additionalProperties:false};
 const tools=[
  {name:'read_store_catalog',title:'Consultar catálogo',description:'Consulta os produtos de demonstração e seus canais de atendimento; valores são ilustrativos.',inputSchema:schemas,annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({products:PRODUCTS,demonstration:store.settings.demo,onlinePaymentAvailable:false})},
  {name:'read_cart_selection',title:'Consultar carrinho',description:'Lê a seleção atual do carrinho de demonstração.',inputSchema:schemas,annotations:{readOnlyHint:true,untrustedContentHint:false},execute:getCart},
  {name:'stage_cart_item',title:'Adicionar item ao carrinho',description:'Adiciona uma unidade de exemplo ao mesmo carrinho da página. Não cria pedido e não cobra pagamentos.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:PRODUCTS.filter(p=>p.mode==='cart').map(p=>p.id)}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.productId!=='string'||Object.keys(input).some(k=>k!=='productId'))throw new Error('Informe apenas productId válido');return addToCart(input.productId)}}
 ];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

})().catch(()=>{const grid=document.querySelector("#product-grid");if(grid)grid.textContent="Não foi possível carregar o catálogo. Atualize a página."});
(()=>{const key='sos-theme';const saved=localStorage.getItem(key);if(saved==='dark'||saved==='light')document.documentElement.dataset.theme=saved;const header=document.querySelector('.header-inner');if(!header||header.querySelector('.theme-toggle'))return;const button=document.createElement('button');button.type='button';button.className='theme-toggle';button.setAttribute('aria-label','Ativar modo noturno');button.innerHTML='<span aria-hidden="true">☾</span><span class="theme-toggle-label">Modo noturno</span>';const update=()=>{const dark=document.documentElement.dataset.theme==='dark';button.setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo noturno');button.innerHTML=dark?'<span aria-hidden="true">☀</span><span class="theme-toggle-label">Modo claro</span>':'<span aria-hidden="true">☾</span><span class="theme-toggle-label">Modo noturno</span>'};button.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem(key,next);update()};header.append(button);update()})();

